INSERT INTO `projects` VALUES (1,'Enterprise E-commerce Microservices','Architect a scalable, high-performance e-commerce platform using a microservices approach. Build separate services for Product Catalog, Order Processing, and User Authentication.','advanced','2025-11-28 06:30:41','2025-11-28 06:30:41'),(2,'Real-time Collaboration Platform','Develop a Slack-like communication tool supporting channels and direct messages. Focus on WebSockets and event-driven architecture.','advanced','2025-11-28 06:30:41','2025-11-28 06:30:41'),(3,'AI-Powered Image Classifier','Build a web application that can classify images uploaded by users. Train a model and deploy it via a FastAPI service.','advanced','2025-11-28 06:30:42','2025-11-28 06:30:42'),(4,'Cross-Platform Fitness Tracker','Create a mobile app to track workouts and diet. Use React Native for cross-platform compatibility and Firebase for the backend.','intermediate','2025-11-28 06:30:42','2025-11-28 06:30:42'),(5,'Secure Banking API','Design a high-security API for financial transactions. Focus on concurrency, data integrity, and secure coding practices.','advanced','2025-11-28 06:30:42','2025-11-28 06:30:42'),(6,'Social Media Sentiment Analysis','Analyze social media posts to determine public sentiment. Use NLP techniques and visualize the results.','intermediate','2025-11-28 06:30:42','2025-11-28 06:30:42'),(7,'Cloud-Native File Storage','Build a Dropbox clone using cloud services. Handle file uploads, storage, and sharing securely.','advanced','2025-11-28 06:30:42','2025-11-28 06:30:42'),(8,'Interactive 3D Product Configurator','Create a web-based 3D car configurator. Users can change colors, wheels, and view the model from all angles.','intermediate','2025-11-28 06:30:42','2025-11-28 06:30:42'),(9,'Automated CI/CD Pipeline Generator','Build a system that automatically sets up CI/CD pipelines for new projects. Focus on automation and infrastructure as code.','advanced','2025-11-28 06:30:42','2025-11-28 06:30:42'),(10,'Music Streaming Service','Develop a mobile music player with backend streaming. Handle audio buffering, playlists, and user libraries.','intermediate','2025-11-28 06:30:42','2025-11-28 06:30:42'),(11,'Corporate Employee Directory','Build an internal directory for a large corporation. Focus on Active Directory integration and enterprise search.','beginner','2025-11-28 06:30:42','2025-11-28 06:30:42'),(12,'Personal Finance Tracker','A simple, responsive web app to track income and expenses. Great for learning Vue.js and reactive data binding.','beginner','2025-11-28 06:30:42','2025-11-28 06:30:42'),(13,'Travel Booking System','Enterprise-grade booking system for flights and hotels. Focus on strict typing, design patterns, and relational data.','intermediate','2025-11-28 06:30:42','2025-11-28 06:30:42'),(14,'Log Analysis & Monitoring Tool','Ingest and visualize server logs. Detect anomalies and alert admins.','advanced','2025-11-28 06:30:42','2025-11-28 06:30:42'),(15,'Smart Home IoT Dashboard','Control smart devices from a central dashboard. Simulate IoT devices using Python scripts.','intermediate','2025-11-28 06:30:42','2025-11-28 06:30:42'),(16,'Classic Blog Platform','Build a standard blog using the Rails framework. Focus on MVC architecture and convention over configuration.','beginner','2025-11-28 06:30:42','2025-11-28 06:30:42'),(17,'High-Performance System Monitor','Build a CLI tool to monitor system resources with minimal overhead. Learn memory safety and systems programming.','advanced','2025-11-28 06:30:42','2025-11-28 06:30:42'),(18,'Next.js E-commerce Storefront','A blazing fast storefront using Server Side Rendering. Focus on SEO and performance.','intermediate','2025-11-28 06:30:42','2025-11-28 06:30:42'),(19,'Svelte Weather App','A lightweight weather application. Experience the compiler-based approach of Svelte.','beginner','2025-11-28 06:30:42','2025-11-28 06:30:42'),(20,'Sales Data Analysis Report','Automate the generation of sales reports from raw CSV data.','beginner','2025-11-28 06:30:42','2025-11-28 06:30:42'),(21,'Personal Portfolio Website','Build a simple static website to showcase your skills. Focus on semantic HTML and basic CSS styling.','beginner','2025-11-28 06:30:42','2025-11-28 06:30:42'),(22,'Interactive Counter App','Create a simple web page with a number and buttons to increment or decrement it. Learn DOM manipulation.','beginner','2025-11-28 06:30:42','2025-11-28 06:30:42'),(23,'Simple To-Do List','Build a list where you can add and remove items. A classic beginner project to master JavaScript events.','beginner','2025-11-28 06:30:42','2025-11-28 06:30:42'),(24,'Login Page UI','Design a beautiful login page. Focus on form styling, input states, and visual design.','beginner','2025-11-28 06:30:42','2025-11-28 06:30:42');
