INSERT INTO `users` VALUES (1,'test','test@mail.com','I ever use PHP to create simple prototype. I use react for UI design. I use python to analyze data.','• **Key Technical Capabilities:**\n    *   Full-Stack Web Development (HTML, CSS, JavaScript, React, PHP, MySQL, SQL)\n    *   Front-End Development (React, Vite)\n    *   Back-End Development (PHP, Python, MySQL, SQL)\n    *   Data Analysis (Python)\n    *   Version Control (Git)\n\n• **Potential Roles:**\n    *   Front-End Developer\n    *   Full-Stack Developer\n    *   Web Developer\n    *   Data Analyst (with web integration skills)\n',NULL,'$2y$12$pApIznsYrokKUJg6iBGs1OSwLxHI6.0WJG1JqdPwzAxPAM0GjZ9Dm',NULL,'2025-11-28 06:32:00','2025-12-05 04:53:58'),(2,'test2','test2@mail.com',NULL,'• Key Capabilities:\n    * Full-stack Web Development: Proficient in both front-end (HTML, CSS, JavaScript, Svelte, Tailwind CSS, Vite) and back-end (PHP, Laravel, Python) technologies.\n    * Modern JavaScript Framework Expertise: Experience with Svelte and tooling like Vite indicates understanding of current best practices.\n    * Back-end Development Flexibility: Familiarity with both PHP/Laravel and Python offers options for different project requirements.\n\n• Potential Roles:\n    * Full-Stack Developer\n    * Front-End Developer (with back-end capabilities)\n    * Back-End Developer (with front-end experience)\n    * Web Application Developer\n',NULL,'$2y$12$rRA7IdYl2cgP8CwqDYTGceEmLS33yu7blHdur.0RJMYmVNPAPfdiW',NULL,'2025-12-05 08:02:20','2025-12-05 08:08:07'),(3,'Test3','test3@mail.com','I ever build a sales reporting system using PhP and MySQL.','• Full Stack Development capabilities\n• Strong proficiency in PHP and JavaScript\n• Experience with Laravel and React ecosystems\n• Potential roles: Full Stack Developer, Backend Engineer\n• AI summarization currently mocked (Gemini disabled)',NULL,'$2y$12$SJn4oBttJfrvTKIQLdE8ruZDsvZ200Kdv2Sv3vtApuvraArCgtBFO',NULL,'2025-12-23 08:53:38','2025-12-23 08:55:02');
